<script setup>
import {computed,ref,watch} from 'vue';import {state,navigate} from '../state';import {t} from '../i18n';import {catalogueReferenceUsage} from '../../core/catalogue-references.mjs';
const props=defineProps({materialId:{type:String,required:true}}),page=ref(1);const rows=computed(()=>catalogueReferenceUsage(state.value,props.materialId)),pages=computed(()=>Math.max(1,Math.ceil(rows.value.length/20))),visible=computed(()=>rows.value.slice((page.value-1)*20,page.value*20));watch(()=>props.materialId,()=>page.value=1);watch(pages,value=>page.value=Math.min(page.value,value));
</script>
<template><section class="panel"><div class="panel-heading"><h2>{{t('catalogueReferenceUsage')}}</h2></div><div class="panel-body"><p class="field-help">{{t('catalogueReferenceHelp')}}</p><p v-if="!rows.length">{{t('none')}}</p><div v-else class="table-wrap"><table><thead><tr><th>{{t('type')}}</th><th>{{t('name')}}</th><th>{{t('catalogueReferencePages')}}</th></tr></thead><tbody><tr v-for="row in visible" :key="`${row.type}:${row.id}`"><td>{{t(row.type==='pattern'?'catalogueReferencePattern':'project')}}</td><td><button class="button text small" @click="navigate(row.type,row.id)">{{row.name}}</button><span v-if="row.archived" class="badge">{{t('archived')}}</span></td><td>{{row.pages||t('unknown')}}</td></tr></tbody></table></div><div v-if="pages>1" class="panel-heading"><span role="status">{{t('page')}} {{page}} / {{pages}}</span><div class="actions"><button class="button small" :disabled="page===1" @click="page--">{{t('previousPage')}}</button><button class="button small" :disabled="page===pages" @click="page++">{{t('nextPage')}}</button></div></div></div></section></template>
